package com.primehr.security;
import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class Phase6cPermissionGuardTest{private final AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);
 @Test void objectivePublishRequiresItsOwnAgencyWidePublishPermission(){PerformanceObjectivePermissionGuard guard=new PerformanceObjectivePermissionGuard(client);when(client.resolve(eq(PerformanceObjectivePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer x")).isInstanceOf(AccessDeniedException.class);when(client.resolve(eq(PerformanceObjectivePermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer x")).isInstanceOf(AccessDeniedException.class);}
 @Test void assignmentActivationRequiresItsOwnAgencyWidePublishPermission(){PerformancePlanAssignmentPermissionGuard guard=new PerformancePlanAssignmentPermissionGuard(client);when(client.resolve(eq(PerformancePlanAssignmentPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,true,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.PUBLISH,"Bearer x")).doesNotThrowAnyException();when(client.resolve(eq(PerformancePlanAssignmentPermissionGuard.FEATURE),anyString())).thenReturn(permission(true,true,false,PermissionDataScope.AGENCY_WIDE));assertThatThrownBy(()->guard.require(PrimeHrAction.PUBLISH,"Bearer x")).isInstanceOf(AccessDeniedException.class);}
 private static EffectiveFeaturePermission permission(boolean access,boolean add,boolean publish,PermissionDataScope scope){return new EffectiveFeaturePermission("x",false,access,add,true,false,publish,false,false,false,false,false,scope);}}
